élément aside. --> </aside> <!-- Ferme l’élément section. --> </section> </template> </main> </template> <style scoped> /* Ouvre un sélecteur CSS à styliser. */ .page { /* Définit une propriété visuelle pour cet élément. */ min-height: 100vh; /* Définit une propriété visuelle pour cet élément. */ padding: 36px 42px; /* Définit une propriété visuelle pour cet élément. */ background: #FFFFFF; /* Ferme le bloc de styles courant. */ } /* Ouvre un sélecteur CSS à styliser. */ .header { /* Définit une propriété visuelle pour cet élément. */ margin-bottom: 25px; /* Ferme le bloc de styles courant. */ } /* Ouvre un sélecteur CSS à styliser. */ .eyebrow { /* Définit une propriété visuelle pour cet élément. */ color: #6372be; /* Définit une propriété visuelle pour cet élément. */ font-size: 9px; /* Définit une propriété visuelle pour cet élément. */ font-weight: 800; /* Définit une propriété visuelle pour cet élément. */ letter-spacing: 0.12em; /* Ferme le bloc de styles courant. */ } /* Ouvre un sélecteur CSS à styliser. */ h1 { /* Définit une propriété visuelle pour cet élément. */ margin: 8px 0 0; /* Définit une propriété visuelle pour cet élément. */ color: #172033; /* Définit une propriété visuelle pour cet élément. */ font-size: 28px; /* Ferme le bloc de styles courant. */ } /* Ouvre un sélecteur CSS à styliser. */ .header p { /* Définit une propriété visuelle pour cet élément. */ margin: 7px 0 0; /* Définit une propriété visuelle pour cet élément. */ color: #7d8797; /* Définit une propriété visuelle pour cet élément. */ font-size: 11px; /* Ferme le bloc de styles courant. */ } /* Ouvre un sélecteur CSS à styliser. */ .validation-layout { /* Définit une propriété visuelle pour cet élément. */ display: grid; /* Définit une propriété visuelle pour cet élément. */ grid-template-columns: /* Définit une propriété visuelle pour cet élément. */ minmax(0, 1fr) /* Définit une propriété visuelle pour cet élément. */ 260px; /* Définit une propriété visuelle pour cet élément. */ ga